// All candles here are SYNTHETIC, generated by a deterministic generator to exercise the engine's logic.
import test from 'node:test';
import assert from 'node:assert/strict';
import { evaluate, qualifies, type EvalInput } from '../src/engine/scoring.ts';
import { DEFAULT_CONFIG, mergeConfig } from '../src/config.ts';
import { NOW_MS, build5m, aggregate, contract, type Shape } from './helpers.ts';

function input(shape: Shape, over: Partial<EvalInput> = {}): EvalInput {
  const c5 = build5m(shape);
  const last = c5[c5.length - 1];
  return {
    symbol: 'SYN_USDT', contract,
    ticker: { symbol: 'SYN_USDT', last: last.c, bid1: last.c * 0.9998, ask1: last.c * 1.0002, volume24: 1, fundingRate: 0.00005, exchangeTs: NOW_MS, receivedTs: NOW_MS, source: 'ws' },
    candles: { Min5: c5, Min15: aggregate(c5, 3, 900), Min60: aggregate(c5, 12, 3600) },
    oiChange30m: { oiPct: 0.03, pricePct: shape.surge === 'down' ? -0.012 : 0.012 },
    usdVolume24h: 20_000_000, spreadBps: 3, change24hPct: 2, nowMs: NOW_MS, ...over,
  };
}

const cfg = DEFAULT_CONFIG;

test('quiet market produces no qualifying candidate', () => {
  const r = evaluate(input({ surge: 'none' }), cfg);
  assert.ok(r.long && r.short);
  assert.ok(r.long!.score < cfg.thresholds.watchScore, `long ${r.long!.score}`);
  assert.ok(r.short!.score < cfg.thresholds.watchScore, `short ${r.short!.score}`);
  assert.equal(r.best === undefined || !qualifies(r.best, cfg), true);
});

test('volume + momentum + close-confirmed breakout -> CONFIRMED LONG with explainable reasons', () => {
  const r = evaluate(input({ surge: 'up' }), cfg);
  assert.ok(r.best, 'a direction must win');
  assert.equal(r.best!.direction, 'LONG');
  assert.equal(r.best!.state, 'CONFIRMED_SETUP', JSON.stringify({ score: r.best!.score, f: r.best!.filters, m: r.best!.metrics }));
  assert.ok(r.best!.score >= cfg.thresholds.confirmScore);
  assert.ok(r.best!.reasons.length >= 2);
  assert.ok(r.best!.invalidation! < r.best!.entryRef && r.best!.target! > r.best!.entryRef);
});

test('mirror case produces SHORT with stop above and target below entry', () => {
  const r = evaluate(input({ surge: 'down' }, { oiChange30m: { oiPct: 0.03, pricePct: -0.012 } }), cfg);
  assert.equal(r.best?.direction, 'SHORT');
  assert.ok(r.best!.invalidation! > r.best!.entryRef);
  assert.ok(r.best!.target! < r.best!.entryRef);
});

test('late-entry filter blocks an already-extended move', () => {
  const r = evaluate(input({ surge: 'up', lateRunPct: 20 }), cfg);
  const long = r.long!;
  assert.equal(long.filters.passed, false);
  assert.ok(long.filters.failures.some((f) => f.startsWith('late entry')));
  assert.equal(long.state === 'CONFIRMED_SETUP', false);
  assert.equal(qualifies(long, cfg), false);
});

test('24h chase limit and liquidity/spread filters', () => {
  assert.ok(evaluate(input({ surge: 'up' }, { change24hPct: 72 }), cfg).long!.filters.failures.some((f) => f.includes('chase limit')));
  assert.ok(evaluate(input({ surge: 'up' }, { usdVolume24h: 500_000 }), cfg).long!.filters.failures.some((f) => f.includes('below minimum')));
  assert.ok(evaluate(input({ surge: 'up' }, { spreadBps: 60 }), cfg).long!.filters.failures.some((f) => f.includes('spread')));
  assert.ok(evaluate(input({ surge: 'up' }, { usdVolume24h: undefined }), cfg).long!.filters.failures.includes('liquidity unknown'));
});

test('unavailable inputs are excluded from the score, not zero-filled, and are listed', () => {
  const noOi = evaluate(input({ surge: 'up' }, { oiChange30m: undefined }), cfg).long!;
  const oi = noOi.components.find((c) => c.key === 'openInterest')!;
  assert.equal(oi.available, false);
  assert.ok(noOi.unavailable.some((u) => u.startsWith('openInterest')));
  assert.ok(noOi.unavailable.some((u) => u.startsWith('orderBook')));
  const withOi = evaluate(input({ surge: 'up' }), cfg).long!;
  assert.ok(withOi.components.find((c) => c.key === 'openInterest')!.available);
});

test('disabling a strategy removes its component from the score', () => {
  const off = mergeConfig(cfg, { strategies: { volumeAnomaly: { enabled: false } } });
  const c = evaluate(input({ surge: 'up' }), off).long!;
  const v = c.components.find((x) => x.key === 'volume')!;
  assert.equal(v.available, false);
  assert.match(v.detail, /disabled/);
});

test('stale or too-short candles are skipped instead of evaluated', () => {
  const i = input({ surge: 'up' });
  const stale = evaluate({ ...i, nowMs: NOW_MS + 3_600_000 }, cfg);
  assert.match(stale.skipped ?? '', /stale/);
  const short = evaluate({ ...i, candles: { Min5: i.candles.Min5!.slice(-10), Min15: i.candles.Min15 } }, cfg);
  assert.match(short.skipped ?? '', /insufficient/);
});

test('a failed breakout is penalised and marked invalidated', () => {
  const i = input({ surge: 'none' });
  const c5 = i.candles.Min5!.map((c) => ({ ...c }));
  const hi = Math.max(...c5.slice(-50, -3).map((c) => c.h));
  const prev = c5[c5.length - 2];
  prev.h = hi * 1.01; prev.c = hi * 0.998; prev.o = hi * 0.999;
  const r = evaluate({ ...i, candles: { ...i.candles, Min5: c5 } }, cfg);
  assert.ok(r.long!.penalties.some((p) => p.key === 'failed_breakout'));
  assert.equal(r.long!.state, 'INVALIDATED_SETUP');
});

test('evaluation is deterministic', () => {
  const a = evaluate(input({ surge: 'up' }), cfg);
  const b = evaluate(input({ surge: 'up' }), cfg);
  assert.deepEqual(a, b);
});

test('score is a transparent weighted mean of available component scores', () => {
  const c = evaluate(input({ surge: 'up' }), cfg).long!;
  const act = c.components.filter((x) => x.available);
  const w = act.reduce((a, x) => a + x.weight, 0);
  const expect = act.reduce((a, x) => a + x.weight * x.score, 0) / w;
  assert.ok(Math.abs(expect - c.rawScore) < 0.06);
});

test('regression: early-bar volume burst is not projected into a huge z-score, and the reason names the bar used', () => {
  const i = input({ surge: 'none' });
  const c5 = i.candles.Min5!.map((c) => ({ ...c }));
  const forming = c5[c5.length - 1];
  const nowEarly = (forming.t + 60) * 1000; // 20% of the bar elapsed -> projection disabled
  forming.v = 2500;
  const early = evaluate({ ...i, nowMs: nowEarly, candles: { ...i.candles, Min5: c5 } }, cfg).long!;
  assert.ok((early.metrics.volumeZ as number) < 3, `early z ${early.metrics.volumeZ}`);
  const late = evaluate({ ...i, nowMs: (forming.t + 240) * 1000, candles: { ...i.candles, Min5: c5 } }, cfg).long!;
  assert.ok((late.metrics.volumeZ as number) <= cfg.thresholds.volumeZ * 2 + 1e-9);
  const vol = late.components.find((c) => c.key === 'volume')!;
  assert.match(vol.detail, /forming 5m bar projected|last closed 5m bar/);
});
